# Surah Al-Mujadala (chapter 58) — part 1: ayat 1-12 (IDs 5105-5116)
SURAH = 58

ENTRIES = {
5105: (
"بسم اللہ الرّحْمٰن الرّحِیْم — اللہ نے اس عورت کی بات سن لی جو تجھ سے اپنے شوہر کے بارے میں جھگڑتی ہے اور اللہ سے فریاد کرتی ہے — اور اللہ تم دونوں کی گفتگو سنتا ہے — بے شک اللہ خوب سننے والا دیکھنے والا ہے",
"""۱۔ خَوْلَہ بنتِ ثعلبہ کا واقعہ — قد سمع الله قول التي تجادلک في زوجها و تشتکي إلی الله؛ و الله یسمع تحاورکما؛ إن الله سمیع بصیر۔
۲۔ ’’قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ وَاللَّهُ يَسْمَعُ تَحَاوُرَكُمَا إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ‘‘ — اللہ نے اس عورت کی بات سن لی جو تجھ سے اپنے شوہر کے بارے میں جھگڑتی ہے اور اللہ سے فریاد کرتی ہے — اور اللہ تم دونوں کی گفتگو سنتا ہے — بے شک اللہ خوب سننے والا دیکھنے والا ہے — یعنی اللہ نے اس عورت کی بات سن لی جو تجھ سے اپنے شوہر کے بارے میں جھگڑتی ہے اور اللہ سے فریاد کرتی ہے اور اللہ تم دونوں کی گفتگو سنتا ہے بے شک اللہ خوب سننے والا دیکھنے والا ہے۔
۳۔ عملی سبق: اللہ تمہاری فریاد سنتا ہے؛ اللہ سے ڈرو۔"""
),
5106: (
"جو تم میں سے اپنی عورتوں سے ب کے الفاظ کہتے ہیں (ظہٰر) — وہ ان کی مائیں نہیں — ان کی مائیں تو صرف وہ ہیں جنہوں نے انہیں جنا ہے — اور بے شک وہ منکر اور جھوٹ بولتے ہیں — اور بے شک اللہ بخشنے والا معاف کرنے والا ہے",
"""۱۔ ظِہار کی حرمت — الذین یظاهرون منکم من نسائهم ما هنّ أمهاتهم؛ إن أمهاتهم إلا اللائي ولدنهم؛ و إنهم لیقولون منکرًا من القول و زورًا؛ و إن الله لعفو غفور۔
۲۔ ’’الَّذِينَ يُظَاهِرُونَ مِنكُم مِّن نِّسَائِهِم مَّا هُنَّ أُمَّهَاتِهِمْ إِنْ أُمَّهَاتُهُمْ إِلَّا اللَّائِي وَلَدْنَهُمْ وَإِنَّهُمْ لَيَقُولُونَ مُنكَرًا مِّنَ الْقَوْلِ وَزُورًا وَإِنَّ اللَّهَ لَعَفُوٌّ غَفُورٌ‘‘ — جو تم میں سے اپنی عورتوں سے ب کے الفاظ کہتے ہیں (ظہٰر) — وہ ان کی مائیں نہیں — ان کی مائیں تو صرف وہ ہیں جنہوں نے انہیں جنا ہے — اور بے شک وہ منکر اور جھوٹ بولتے ہیں — اور بے شک اللہ بخشنے والا معاف کرنے والا ہے — یعنی جو تم میں سے اپنی عورتوں سے ب کے الفاظ کہتے ہیں وہ ان کی مائیں نہیں ان کی مائیں تو صرف وہ ہیں جنہوں نے انہیں جنا ہے اور بے شک وہ منکر اور جھوٹ بولتے ہیں اور بے شک اللہ بخشنے والا معاف کرنے والا ہے۔
۳۔ عملی سبق: ظہار کا جھوٹا بہانہ چھوڑو؛ اللہ سے ڈرو۔"""
),
5107: (
"اور جو اپنی عورتوں سے ب کے الفاظ کہتے ہیں پھر لوٹتے ہیں اس سے جو کہا — تو انہیں چھونے سے پہلے ایک غلام آزاد کریں — یہی تمہیں نصیحت کی جاتی ہے — اور اللہ جو تم کرتے ہو اس سے باخبر ہے",
"""۱۔ ظہار کا کفارہ — و الذین یظاهرون من نسائهم ثم یعودون لما قالوا فتحریر رقبة من قبل أن یتماسا؛ ذلکم توعَظون به؛ و الله بما تعملون خبیر۔
۲۔ ’’وَالَّذِينَ يُظَاهِرُونَ مِن نِّسَائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا فَتَحْرِيرُ رَقَبَۃٍ مِّن قَبْلِ أَن يَتَمَاسَّا ذَٰلِكُمْ تُوعَظُونَ بِهِ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ‘‘ — اور جو اپنی عورتوں سے ب کے الفاظ کہتے ہیں پھر لوٹتے ہیں اس سے جو کہا — تو انہیں چھونے سے پہلے ایک غلام آزاد کریں — یہی تمہیں نصیحت کی جاتی ہے — اور اللہ جو تم کرتے ہو اس سے باخبر ہے — یعنی اور جو اپنی عورتوں سے ب کے الفاظ کہتے ہیں پھر لوٹتے ہیں اس سے جو کہا تو انہیں چھونے سے پہلے ایک غلام آزاد کریں یہی تمہیں نصیحت کی جاتی ہے اور اللہ جو تم کرتے ہو اس سے باخبر ہے۔
۳۔ عملی سبق: ظہار کے گناہ سے بچو؛ اللہ سے ڈرو۔"""
),
5108: (
"اور جسے غلام نہ ملے تو چھونے سے پہلے مسلسل دو مہینے روزے رکھے — اور جو اس کی بھی طاقت نہ رکھے تو ساٹھ مساکین کو کھانا کھلائے — یہ اس لیے تاکہ تم اللہ اور اس کے رسول پر ایمان لاؤ — اور یہ اللہ کی حدیں ہیں — اور کافروں کے لیے دردناک عذاب ہے",
"""۱۔ کفارہ کی صورتیں — فمن لم یجد فصیام شهرین متتابعین من قبل أن یتماسا؛ فمن لم یستطع فإطعام ستين مسکینًا؛ ذلک لتؤمنوا بالله و رسوله؛ و تلک حدود الله؛ و للکافرین عذاب الیم۔
۲۔ ’’فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَن يَتَمَاسَّا فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا ذَٰلِكَ لِتُؤْمِنُوا بِاللَّهِ وَرَسُولِهِ وَتِلْكَ حُدُودُ اللَّهِ وَلِلْكَافِرِينَ عَذَابٌ أَلِيمٌ‘‘ — اور جسے غلام نہ ملے تو چھونے سے پہلے مسلسل دو مہینے روزے رکھے — اور جو اس کی بھی طاقت نہ رکھے تو ساٹھ مساکین کو کھانا کھلائے — یہ اس لیے تاکہ تم اللہ اور اس کے رسول پر ایمان لاؤ — اور یہ اللہ کی حدیں ہیں — اور کافروں کے لیے دردناک عذاب ہے — یعنی اور جسے غلام نہ ملے تو چھونے سے پہلے مسلسل دو مہینے روزے رکھے اور جو اس کی بھی طاقت نہ رکھے تو ساٹھ مساکین کو کھانا کھلائے یہ اس لیے تاکہ تم اللہ اور اس کے رسول پر ایمان لاؤ اور یہ اللہ کی حدیں ہیں اور کافروں کے لیے دردناک عذاب ہے۔
۳۔ عملی سبق: اللہ کی حدود کی پامالی نہ کرو؛ اللہ سے ڈرو۔"""
),
5109: (
"بے شک جو اللہ اور اس کے رسول سے دشمنی کرتے ہیں وہ ذلیل کر دیے جائیں گے جیسے ان سے پہلے والے ذلیل کیے گئے — اور ہم نے کھلی آیات نازل کی ہیں — اور کافروں کے لیے ذلیل کرنے والا عذاب ہے",
"""۱۔ دشمنِ اللہ کا انجام — إن الذین یحادّون الله و رسوله کُبِتوا کما کُبِت الذین من قبلهم؛ و قد أنزلنا آیات بینات؛ و للکافرین عذاب مهین۔
۲۔ ’’إِنَّ الَّذِينَ يُحَادُّونَ اللَّهَ وَرَسُولَهُ كُبِتُوا كَمَا كُبِتَ الَّذِينَ مِن قَبْلِهِمْ وَقَدْ أَنزَلْنَا آيَاتٍ بَيِّنَاتٍ وَلِلْكَافِرِينَ عَذَابٌ مُّهِينٌ‘‘ — بے شک جو اللہ اور اس کے رسول سے دشمنی کرتے ہیں وہ ذلیل کر دیے جائیں گے جیسے ان سے پہلے والے ذلیل کیے گئے — اور ہم نے کھلی آیات نازل کی ہیں — اور کافروں کے لیے ذلیل کرنے والا عذاب ہے — یعنی بے شک جو اللہ اور اس کے رسول سے دشمنی کرتے ہیں وہ ذلیل کر دیے جائیں گے جیسے ان سے پہلے والے ذلیل کیے گئے اور ہم نے کھلی آیات نازل کی ہیں اور کافروں کے لیے ذلیل کرنے والا عذاب ہے۔
۳۔ عملی سبق: اللہ اور رسول سے دشمنی نہ کرو؛ اللہ سے ڈرو۔"""
),
5110: (
"جس دن اللہ سب کو اٹھائے گا اور انہیں ان کے اعمال بتائے گا — اللہ نے انہیں گِنا اور وہ بھول گئے — اور اللہ ہر چیز پر گواہ ہے",
"""۱۔ اعمال کا حساب — یوم یبعثهم الله جمیعًا فینبئهم بما عملوا؛ أحصاه الله و نسوه؛ و الله علی کل شيء شهید۔
۲۔ ’’يَوْمَ يَبْعَثُهُمُ اللَّهُ جَمِيعًا فَيُنَبِّئُهُم بِمَا عَمِلُوا أَحْصَاهُ اللَّهُ وَنَسُوهُ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ‘‘ — جس دن اللہ سب کو اٹھائے گا اور انہیں ان کے اعمال بتائے گا — اللہ نے انہیں گِنا اور وہ بھول گئے — اور اللہ ہر چیز پر گواہ ہے — یعنی جس دن اللہ سب کو اٹھائے گا اور انہیں ان کے اعمال بتائے گا اللہ نے انہیں گِنا اور وہ بھول گئے اور اللہ ہر چیز پر گواہ ہے۔
۳۔ عملی سبق: ہر عمل لکھا جا رہا ہے؛ اللہ سے ڈرو۔"""
),
5111: (
"کیا تو نہیں دیکھتا کہ اللہ آسمانوں اور زمین میں جو ہے اسے جانتا ہے — کوئی سرگوشی نہیں ہوتی تین میں مگر وہ ان کا چوتھا ہے اور نہ پانچ میں مگر وہ ان کا چھٹا ہے — اور نہ اس سے کم میں نہ زیادہ میں مگر وہ ان کے ساتھ ہے جہاں بھی ہوں — پھر وہ انہیں قیامت کے دن ان کے اعمال بتائے گا — بے شک اللہ ہر چیز کا جاننے والا ہے",
"""۱۔ اللہ کا علم — ألم تر أن الله یعلم ما في السماوات و ما في الأرض؛ ما یکون من نجوی ثلاثة إلا هو رابعهم و لا خامسة إلا هو سادسهم و لا أدنی من ذلک و لا أکثر إلا هو معهم أینما کانوا؛ ثم ینبئهم بما عملوا یوم القیامة؛ إن الله بکل شيء علیم۔
۲۔ ’’أَلَمْ تَرَ أَنَّ اللَّهَ يَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَاثَۃٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَۃٍ إِلَّا هُوَ سَادِسُهُمْ وَلَا أَدْنَىٰ مِن ذَٰلِكَ وَلَا أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا يَوْمَ الْقِيَامَۃِ إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ‘‘ — کیا تو نہیں دیکھتا کہ اللہ آسمانوں اور زمین میں جو ہے اسے جانتا ہے — کوئی سرگوشی نہیں ہوتی تین میں مگر وہ ان کا چوتھا ہے اور نہ پانچ میں مگر وہ ان کا چھٹا ہے — اور نہ اس سے کم میں نہ زیادہ میں مگر وہ ان کے ساتھ ہے جہاں بھی ہوں — پھر وہ انہیں قیامت کے دن ان کے اعمال بتائے گا — بے شک اللہ ہر چیز کا جاننے والا ہے — یعنی کیا تو نہیں دیکھتا کہ اللہ آسمانوں اور زمین میں جو ہے اسے جانتا ہے کوئی سرگوشی نہیں ہوتی تین میں مگر وہ ان کا چوتھا ہے اور نہ پانچ میں مگر وہ ان کا چھٹا ہے اور نہ اس سے کم میں نہ زیادہ میں مگر وہ ان کے ساتھ ہے جہاں بھی ہوں پھر وہ انہیں قیامت کے دن ان کے اعمال بتائے گا بے شک اللہ ہر چیز کا جاننے والا ہے۔
۳۔ عملی سبق: اللہ ہر سرگوشی سنتا ہے؛ اللہ سے ڈرو۔"""
),
5112: (
"کیا تو نہیں دیکھتا انہیں جو سرگوشی سے روکے گئے پھر وہ اس میں لوٹتے ہیں جس سے روکے گئے اور گناہ اور زیادتی اور رسول کی نافرمانی پر سرگوشی کرتے ہیں — اور جب تیرے پاس آتے ہیں تو تجھے ایسے الفاظ سے سلام کرتے ہیں جن سے اللہ نے تجھے سلام نہیں کیا — اور اپنے دلوں میں کہتے ہیں اللہ ہمیں ہماری باتوں پر سزا کیوں نہیں دیتا — ان کے لیے جہنم کافی ہے جس میں وہ داخل ہوں گے — اور بہت بری جگہ ہے",
"""۱۔ یہودیوں کی سرگوشی — ألم تر إلی الذین نهوا عن النجوی ثم یعودون لما نهوا عنه و یتناجون بالإثم و العدوان و معصیت الرسول؛ و إذا جاءوک حیوک بما لم یُحِیّک به الله و یقولون في أنفسهم لولا یُعذّبنا الله بما نقول؛ حسبهم جهنم یصلونها؛ فبئس المصیر۔
۲۔ ’’أَلَمْ تَرَ إِلَى الَّذِينَ نُهُوا عَنِ النَّجْوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُوا عَنْهُ وَيَتَنَاجَوْنَ بِالْإِثْمِ وَالْعُدْوَانِ وَمَعْصِيَتِ الرَّسُولِ وَإِذَا جَاءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ اللَّهُ وَيَقُولُونَ فِي أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا اللَّهُ بِمَا نَقُولُ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَهَا فَبِئْسَ الْمَصِيرُ‘‘ — کیا تو نہیں دیکھتا انہیں جو سرگوشی سے روکے گئے پھر وہ اس میں لوٹتے ہیں جس سے روکے گئے اور گناہ اور زیادتی اور رسول کی نافرمانی پر سرگوشی کرتے ہیں — اور جب تیرے پاس آتے ہیں تو تجھے ایسے الفاظ سے سلام کرتے ہیں جن سے اللہ نے تجھے سلام نہیں کیا — اور اپنے دلوں میں کہتے ہیں اللہ ہمیں ہماری باتوں پر سزا کیوں نہیں دیتا — ان کے لیے جہنم کافی ہے جس میں وہ داخل ہوں گے — اور بہت بری جگہ ہے — یعنی کیا تو نہیں دیکھتا انہیں جو سرگوشی سے روکے گئے پھر وہ اس میں لوٹتے ہیں جس سے روکے گئے اور گناہ اور زیادتی اور رسول کی نافرمانی پر سرگوشی کرتے ہیں اور جب تیرے پاس آتے ہیں تو تجھے ایسے الفاظ سے سلام کرتے ہیں جن سے اللہ نے تجھے سلام نہیں کیا اور اپنے دلوں میں کہتے ہیں اللہ ہمیں ہماری باتوں پر سزا کیوں نہیں دیتا ان کے لیے جہنم کافی ہے جس میں وہ داخل ہوں گے اور بہت بری جگہ ہے۔
۳۔ عملی سبق: گناہ پر سرگوشی نہ کرو؛ اللہ سے ڈرو۔"""
),
5113: (
"اے ایمان والو جب تم سرگوشی کرو تو گناہ زیادتی اور رسول کی نافرمانی پر نہ کرو — اور نیکی اور تقویٰ پر سرگوشی کرو — اور اللہ سے ڈرو جس کی طرف تم جمع کیے جاؤ گے",
"""۱۔ نیکی پر سرگوشی — یا أیها الذین آمنوا إذا تناجيتم فلا تتناجوا بالإثم و العدوان و معصيت الرسول؛ و تناجوا بالبر و التقوی؛ و اتقوا الله الذي إلیه تحشرون۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَنَاجَيْتُمْ فَلَا تَتَنَاجَوْا بِالْإِثْمِ وَالْعُدْوَانِ وَمَعْصِيَتِ الرَّسُولِ وَتَنَاجَوْا بِالْبِرِّ وَالتَّقْوَىٰ وَاتَّقُوا اللَّهَ الَّذِي إِلَيْهِ تُحْشَرُونَ‘‘ — اے ایمان والو جب تم سرگوشی کرو تو گناہ زیادتی اور رسول کی نافرمانی پر نہ کرو — اور نیکی اور تقویٰ پر سرگوشی کرو — اور اللہ سے ڈرو جس کی طرف تم جمع کیے جاؤ گے — یعنی اے ایمان والو جب تم سرگوشی کرو تو گناہ زیادتی اور رسول کی نافرمانی پر نہ کرو اور نیکی اور تقویٰ پر سرگوشی کرو اور اللہ سے ڈرو جس کی طرف تم جمع کیے جاؤ گے۔
۳۔ عملی سبق: نیکی اور تقویٰ پر سرگوشی کرو؛ اللہ سے ڈرو۔"""
),
5114: (
"سرگوشی تو شیطان کی طرف سے ہے تاکہ ایمان والوں کو دکھ دے — اور وہ انہیں نقصان نہیں پہنچا سکتا مگر اللہ کے اذن سے — اور اللہ پر ہی ایمان والوں کو توکل کرنا چاہیے",
"""۱۔ سرگوشی شیطان کی ہے — إنما النجوی من الشیطان لیحزن الذین آمنوا؛ و لیس بضارهم شيئًا إلا بإذن الله؛ و علی الله فلیتوکل المؤمنون۔
۲۔ ’’إِنَّمَا النَّجْوَىٰ مِنَ الشَّيْطَانِ لِيَحْزُنَ الَّذِينَ آمَنُوا وَلَيْسَ بِضَارِّهِمْ شَيْئًا إِلَّا بِإِذْنِ اللَّهِ وَعَلَى اللَّهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ‘‘ — سرگوشی تو شیطان کی طرف سے ہے تاکہ ایمان والوں کو دکھ دے — اور وہ انہیں نقصان نہیں پہنچا سکتا مگر اللہ کے اذن سے — اور اللہ پر ہی ایمان والوں کو توکل کرنا چاہیے — یعنی سرگوشی تو شیطان کی طرف سے ہے تاکہ ایمان والوں کو دکھ دے اور وہ انہیں نقصان نہیں پہنچا سکتا مگر اللہ کے اذن سے اور اللہ پر ہی ایمان والوں کو توکل کرنا چاہیے۔
۳۔ عملی سبق: شیطان سے بچو؛ اللہ پر توکل کرو؛ اللہ سے ڈرو۔"""
),
5115: (
"اے ایمان والو جب تم سے کہا جائے مجلسوں میں کشادہ ہو جاؤ تو کشادہ ہو جاؤ اللہ تمہارے لیے کشادہ کرے گا — اور جب کہا جائے اٹھ جاؤ تو اٹھ جاؤ اللہ انہیں جو تم میں سے ایمان لائے اور جنہیں علم دیا گیا درجے بلند کرے گا — اور اللہ جو تم کرتے ہو اس سے باخبر ہے",
"""۱۔ مجلسوں میں کشادہ — یا أیها الذین آمنوا إذا قیل لکم تفسحوا في المجالس فافسحوا یفسح الله لکم؛ و إذا قیل انشزوا فانشزوا یرفع الله الذین آمنوا منکم و الذین أوتوا العلم درجات؛ و الله بما تعملون خبیر۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قِيلَ لَكُمْ تَفَسَّحُوا فِي الْمَجَالِسِ فَافْسَحُوا يَفْسَحِ اللَّهُ لَكُمْ وَإِذَا قِيلَ انشُزُوا فَانشُزُوا يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ‘‘ — اے ایمان والو جب تم سے کہا جائے مجلسوں میں کشادہ ہو جاؤ تو کشادہ ہو جاؤ اللہ تمہارے لیے کشادہ کرے گا — اور جب کہا جائے اٹھ جاؤ تو اٹھ جاؤ اللہ انہیں جو تم میں سے ایمان لائے اور جنہیں علم دیا گیا درجے بلند کرے گا — اور اللہ جو تم کرتے ہو اس سے باخبر ہے — یعنی اے ایمان والو جب تم سے کہا جائے مجلسوں میں کشادہ ہو جاؤ تو کشادہ ہو جاؤ اللہ تمہارے لیے کشادہ کرے گا اور جب کہا جائے اٹھ جاؤ تو اٹھ جاؤ اللہ انہیں جو تم میں سے ایمان لائے اور جنہیں علم دیا گیا درجے بلند کرے گا اور اللہ جو تم کرتے ہو اس سے باخبر ہے۔
۳۔ عملی سبق: مجلسوں میں کشادگی کرو؛ علم حاصل کرو؛ اللہ سے ڈرو۔"""
),
5116: (
"اے ایمان والو جب تم رسول سے سرگوشی کرو تو اپنی سرگوشی سے پہلے صدقہ پیش کرو — یہ تمہارے لیے بہتر اور زیادہ پاک ہے — پس اگر تم نہ پاؤ تو بے شک اللہ غفور رحیم ہے",
"""۱۔ سرگوشی سے پہلے صدقہ — یا أیها الذین آمنوا إذا ناجیتم الرسول فقدموا بین یدي نجواکم صدقة؛ ذلک خیر لکم و أطهر؛ فإن لم تجدوا فإن الله غفور رحیم۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَاجَيْتُمُ الرَّسُولَ فَقَدِّمُوا بَيْنَ يَدَيْ نَجْوَاكُمْ صَدَقَۃً ذَٰلِكَ خَيْرٌ لَّكُمْ وَأَطْهَرُ فَإِن لَّمْ تَجِدُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ‘‘ — اے ایمان والو جب تم رسول سے سرگوشی کرو تو اپنی سرگوشی سے پہلے صدقہ پیش کرو — یہ تمہارے لیے بہتر اور زیادہ پاک ہے — پس اگر تم نہ پاؤ تو بے شک اللہ غفور رحیم ہے — یعنی اے ایمان والو جب تم رسول سے سرگوشی کرو تو اپنی سرگوشی سے پہلے صدقہ پیش کرو یہ تمہارے لیے بہتر اور زیادہ پاک ہے پس اگر تم نہ پاؤ تو بے شک اللہ غفور رحیم ہے۔
۳۔ عملی سبق: رسول کی خدمت کرو؛ صدقہ دو؛ اللہ سے ڈرو۔"""
),
}
